-- Phase 30: the fiscal invoicing engine's tables (SPEC core 10).
--
-- invoice_sequences is the gap-free Bill Number counter: one row per seller, Nepal fiscal year
-- and document type, locked FOR UPDATE and raised by one inside the issuing transaction (never a
-- SEQUENCE, which burns a number on rollback). invoices holds the invoice header and totals.
-- Generated by drizzle-kit; the triggers at the end are hand-added:
--   invoices           UPDATE, DELETE and TRUNCATE are refused for every role: an invoice is sealed
--   invoice_sequences  a row starts at 0, changes only by last_number + 1, and is never removed
CREATE TYPE "public"."fiscal_document_type" AS ENUM('INVOICE', 'CREDIT_NOTE', 'DEBIT_NOTE');--> statement-breakpoint
CREATE TABLE "invoice_sequences" (
	"vendor_id" uuid NOT NULL,
	"fiscal_year" text NOT NULL,
	"document_type" "fiscal_document_type" NOT NULL,
	"last_number" integer DEFAULT 0 NOT NULL,
	CONSTRAINT "invoice_sequences_vendor_id_fiscal_year_document_type_pk" PRIMARY KEY("vendor_id","fiscal_year","document_type"),
	CONSTRAINT "invoice_sequences_fiscal_year_check" CHECK ("invoice_sequences"."fiscal_year" ~ '^[0-9]{4}/[0-9]{3}$'),
	CONSTRAINT "invoice_sequences_last_number_check" CHECK ("invoice_sequences"."last_number" >= 0)
);
--> statement-breakpoint
CREATE TABLE "invoices" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"document_type" "fiscal_document_type" DEFAULT 'INVOICE' NOT NULL,
	"vendor_id" uuid NOT NULL,
	"order_id" uuid NOT NULL,
	"customer_id" uuid NOT NULL,
	"fiscal_year" text NOT NULL,
	"bill_number" integer NOT NULL,
	"invoice_sequence" text NOT NULL,
	"issued_at" timestamp with time zone NOT NULL,
	"issued_date_bs" text NOT NULL,
	"subtotal_npr" numeric(12, 2) NOT NULL,
	"discount_npr" numeric(12, 2) DEFAULT 0 NOT NULL,
	"delivery_charge_npr" numeric(12, 2) DEFAULT 0 NOT NULL,
	"grand_total_npr" numeric(12, 2) NOT NULL,
	CONSTRAINT "invoices_bill_number_key" UNIQUE("vendor_id","document_type","fiscal_year","bill_number"),
	CONSTRAINT "invoices_fiscal_year_check" CHECK ("invoices"."fiscal_year" ~ '^[0-9]{4}/[0-9]{3}$'),
	CONSTRAINT "invoices_bill_number_check" CHECK ("invoices"."bill_number" >= 1),
	CONSTRAINT "invoices_invoice_sequence_check" CHECK (btrim("invoices"."invoice_sequence") <> ''),
	CONSTRAINT "invoices_issued_date_bs_check" CHECK ("invoices"."issued_date_bs" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'),
	CONSTRAINT "invoices_amounts_check" CHECK ("invoices"."subtotal_npr" >= 0 AND "invoices"."discount_npr" >= 0 AND "invoices"."delivery_charge_npr" >= 0
            AND "invoices"."discount_npr" <= "invoices"."subtotal_npr"),
	CONSTRAINT "invoices_grand_total_check" CHECK ("invoices"."grand_total_npr" = "invoices"."subtotal_npr" - "invoices"."discount_npr" + "invoices"."delivery_charge_npr")
);
--> statement-breakpoint
ALTER TABLE "invoice_sequences" ADD CONSTRAINT "invoice_sequences_vendor_id_vendors_id_fk" FOREIGN KEY ("vendor_id") REFERENCES "public"."vendors"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_vendor_id_vendors_id_fk" FOREIGN KEY ("vendor_id") REFERENCES "public"."vendors"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_customer_id_users_id_fk" FOREIGN KEY ("customer_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "invoices_order_invoice_uidx" ON "invoices" USING btree ("order_id") WHERE "invoices"."document_type" = 'INVOICE';--> statement-breakpoint
CREATE INDEX "invoices_order_id_idx" ON "invoices" USING btree ("order_id");--> statement-breakpoint
CREATE INDEX "invoices_customer_id_idx" ON "invoices" USING btree ("customer_id");--> statement-breakpoint
CREATE INDEX "invoices_vendor_list_idx" ON "invoices" USING btree ("vendor_id","fiscal_year","issued_at","id");
