-- Hand-added: an issued invoice is sealed.
CREATE FUNCTION reject_invoice_mutation() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'invoices are immutable (% rejected)', TG_OP USING ERRCODE = '23000';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER invoices_immutable BEFORE UPDATE OR DELETE ON invoices
  FOR EACH ROW EXECUTE FUNCTION reject_invoice_mutation();
--> statement-breakpoint
CREATE TRIGGER invoices_no_truncate BEFORE TRUNCATE ON invoices
  FOR EACH STATEMENT EXECUTE FUNCTION reject_invoice_mutation();
--> statement-breakpoint
-- Hand-added: the counter only counts up by one.
CREATE FUNCTION guard_invoice_sequence() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.last_number <> 0 THEN
      RAISE EXCEPTION 'an invoice sequence starts at 0' USING ERRCODE = '23000';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.vendor_id = OLD.vendor_id
     AND NEW.fiscal_year = OLD.fiscal_year
     AND NEW.document_type = OLD.document_type
     AND NEW.last_number = OLD.last_number + 1 THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'an invoice sequence only counts up by one (% rejected)', TG_OP
    USING ERRCODE = '23000';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER invoice_sequences_guard BEFORE INSERT OR UPDATE OR DELETE ON invoice_sequences
  FOR EACH ROW EXECUTE FUNCTION guard_invoice_sequence();
--> statement-breakpoint
CREATE TRIGGER invoice_sequences_no_truncate BEFORE TRUNCATE ON invoice_sequences
  FOR EACH STATEMENT EXECUTE FUNCTION guard_invoice_sequence();
